CREATE TRIGGER trg_change_bu BEFORE UPDATE ON change
WHEN NOT (OLD.change_set_id IS NULL AND NEW.change_set_id IS NOT NULL
          AND NEW.id = OLD.id AND NEW.ts = OLD.ts AND NEW.table_name = OLD.table_name
          AND NEW.row_key = OLD.row_key AND NEW.op = OLD.op
          AND NEW.before_json IS OLD.before_json AND NEW.after_json IS OLD.after_json)
BEGIN SELECT RAISE(ABORT, 'change is append-only'); END;
CREATE TRIGGER trg_change_bd BEFORE DELETE ON change
BEGIN SELECT RAISE(ABORT, 'change is append-only'); END;
CREATE TRIGGER trg_change_set_bu BEFORE UPDATE ON change_set
WHEN NOT (OLD.id IS (SELECT change_set_id FROM app_context WHERE id = 1)
          AND NEW.id = OLD.id AND NEW.ts = OLD.ts AND NEW.actor = OLD.actor
          AND NEW.reverts_change_set_id IS OLD.reverts_change_set_id)
BEGIN SELECT RAISE(ABORT, 'change_set is append-only (only the open set label may change)'); END;
CREATE TRIGGER trg_change_set_bd BEFORE DELETE ON change_set
BEGIN SELECT RAISE(ABORT, 'change_set is append-only'); END;
CREATE TRIGGER trg_item_lock_bu BEFORE UPDATE ON item
WHEN OLD.origin IN ('outlook', 'ics')
 AND (SELECT actor FROM app_context WHERE id = 1) NOT IN ('sync', 'undo')
 AND (OLD.title IS NOT NEW.title
      OR OLD.start_date IS NOT NEW.start_date
      OR OLD.end_date IS NOT NEW.end_date
      OR OLD.kind IS NOT NEW.kind
      OR OLD.origin IS NOT NEW.origin
      OR OLD.source_id IS NOT NEW.source_id
      OR OLD.outlook_uid IS NOT NEW.outlook_uid
      OR OLD.ics_uid IS NOT NEW.ics_uid
      OR OLD.outlook_series_id IS NOT NEW.outlook_series_id
      OR OLD.outlook_calendar IS NOT NEW.outlook_calendar
      OR OLD.outlook_time IS NOT NEW.outlook_time
      OR OLD.outlook_location IS NOT NEW.outlook_location)
BEGIN SELECT RAISE(ABORT, 'Imported item: core fields are locked'); END;
CREATE TRIGGER trg_item_nodelete_bd BEFORE DELETE ON item
WHEN (SELECT actor FROM app_context WHERE id = 1) <> 'undo'
BEGIN SELECT RAISE(ABORT, 'Hard delete is not allowed: set deleted_at instead'); END;
CREATE TRIGGER trg_file_version_bu BEFORE UPDATE ON file_version
BEGIN SELECT RAISE(ABORT, 'file_version rows are immutable'); END;
CREATE TRIGGER trg_file_version_bd BEFORE DELETE ON file_version
WHEN EXISTS (SELECT 1 FROM attachment WHERE pinned_version_id = OLD.id)
  OR EXISTS (SELECT 1 FROM change WHERE table_name = 'attachment'
             AND (instr(before_json, OLD.id) > 0 OR instr(after_json, OLD.id) > 0))
BEGIN SELECT RAISE(ABORT, 'file_version is still referenced by a link or the undo history'); END;
CREATE TRIGGER trg_tag_cycle_bu BEFORE UPDATE OF parent_id ON tag
WHEN NEW.parent_id IS NOT NULL AND NEW.parent_id IN (WITH RECURSIVE des(id, d) AS (SELECT NEW.id, 0 UNION ALL SELECT t.id, des.d + 1 FROM tag t JOIN des ON t.parent_id = des.id WHERE des.d < 64) SELECT id FROM des)
BEGIN SELECT RAISE(ABORT, 'A tag group cannot contain itself'); END;
CREATE TRIGGER trg_item_tag_tree_bd BEFORE DELETE ON item_tag
WHEN (SELECT actor FROM app_context WHERE id = 1) <> 'undo'
 AND EXISTS (SELECT 1 FROM item_tag x WHERE x.item_id = OLD.item_id AND x.implied = 0 AND x.tag_id <> OLD.tag_id
             AND OLD.tag_id IN (WITH RECURSIVE anc(id, d) AS (SELECT parent_id, 1 FROM tag WHERE id = x.tag_id AND parent_id IS NOT NULL UNION ALL SELECT t.parent_id, anc.d + 1 FROM tag t JOIN anc ON t.id = anc.id WHERE t.parent_id IS NOT NULL AND anc.d < 64) SELECT id FROM anc))
BEGIN SELECT RAISE(ABORT, 'Remove the descendant tag first'); END;
CREATE TRIGGER trg_item_tag_tree_ai AFTER INSERT ON item_tag
WHEN NEW.implied = 0 AND (SELECT actor FROM app_context WHERE id = 1) <> 'undo'
BEGIN
  INSERT INTO item_tag (item_id, tag_id, position, implied)
  SELECT NEW.item_id, a.id, (SELECT coalesce(max(p.position), -1) FROM item_tag p WHERE p.item_id = NEW.item_id AND p.position < 1000) + a.d, 1
    FROM (WITH RECURSIVE anc(id, d) AS (SELECT parent_id, 1 FROM tag WHERE id = NEW.tag_id AND parent_id IS NOT NULL
            UNION ALL SELECT t.parent_id, anc.d + 1 FROM tag t JOIN anc ON t.id = anc.id
            WHERE t.parent_id IS NOT NULL AND anc.d < 64) SELECT id, d FROM anc) a
   WHERE NOT EXISTS (SELECT 1 FROM item_tag x WHERE x.item_id = NEW.item_id AND x.tag_id = a.id);
END;
CREATE TRIGGER trg_item_tag_tree_ad AFTER DELETE ON item_tag
WHEN OLD.implied = 0 AND (SELECT actor FROM app_context WHERE id = 1) <> 'undo'
BEGIN
  DELETE FROM item_tag
   WHERE item_id = OLD.item_id AND implied = 1
     AND NOT EXISTS (SELECT 1 FROM item_tag x WHERE x.item_id = OLD.item_id AND x.implied = 0
                     AND item_tag.tag_id IN (WITH RECURSIVE anc(id, d) AS (SELECT parent_id, 1 FROM tag WHERE id = x.tag_id AND parent_id IS NOT NULL UNION ALL SELECT t.parent_id, anc.d + 1 FROM tag t JOIN anc ON t.id = anc.id WHERE t.parent_id IS NOT NULL AND anc.d < 64) SELECT id FROM anc));
END;
CREATE TRIGGER trg_tag_tree_au AFTER UPDATE OF parent_id ON tag
WHEN OLD.parent_id IS NOT NEW.parent_id AND (SELECT actor FROM app_context WHERE id = 1) <> 'undo'
BEGIN
  DELETE FROM item_tag
   WHERE implied = 1
     AND item_id IN (SELECT item_id FROM item_tag WHERE implied = 0 AND tag_id IN (WITH RECURSIVE des(id, d) AS (SELECT NEW.id, 0 UNION ALL SELECT t.id, des.d + 1 FROM tag t JOIN des ON t.parent_id = des.id WHERE des.d < 64) SELECT id FROM des))
     AND NOT EXISTS (SELECT 1 FROM item_tag x WHERE x.item_id = item_tag.item_id AND x.implied = 0
                     AND item_tag.tag_id IN (WITH RECURSIVE anc(id, d) AS (SELECT parent_id, 1 FROM tag WHERE id = x.tag_id AND parent_id IS NOT NULL UNION ALL SELECT t.parent_id, anc.d + 1 FROM tag t JOIN anc ON t.id = anc.id WHERE t.parent_id IS NOT NULL AND anc.d < 64) SELECT id FROM anc));
  INSERT INTO item_tag (item_id, tag_id, position, implied)
  SELECT x.item_id, c.anc_id, (SELECT coalesce(max(p.position), -1) FROM item_tag p WHERE p.item_id = x.item_id AND p.position < 1000) + min(c.d), 1
    FROM item_tag x JOIN (WITH RECURSIVE cl(tag_id, anc_id, d) AS (SELECT id, parent_id, 1 FROM tag WHERE parent_id IS NOT NULL UNION ALL SELECT cl.tag_id, t.parent_id, cl.d + 1 FROM cl JOIN tag t ON t.id = cl.anc_id WHERE t.parent_id IS NOT NULL AND cl.d < 64) SELECT tag_id, anc_id, d FROM cl) c ON c.tag_id = x.tag_id
   WHERE x.implied = 0
     AND x.item_id IN (SELECT item_id FROM item_tag WHERE implied = 0 AND tag_id IN (WITH RECURSIVE des(id, d) AS (SELECT NEW.id, 0 UNION ALL SELECT t.id, des.d + 1 FROM tag t JOIN des ON t.parent_id = des.id WHERE des.d < 64) SELECT id FROM des))
     AND NOT EXISTS (SELECT 1 FROM item_tag y WHERE y.item_id = x.item_id AND y.tag_id = c.anc_id)
   GROUP BY x.item_id, c.anc_id;
END;
